INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(4250, 'metaphor', '/ˈmetəfɔːr/', 'noun', '{"zh-TW":["隱喻；比喻"],"en":["a figure of speech in which a word is applied to something it cannot literally describe"]}', NULL, 'use a metaphor / apt metaphor / powerful metaphor', '[{"en":"The CEO used the metaphor of a ship to describe the company''s direction.","zh-TW":"CEO用一艘船的隱喻來描述公司的方向。"},{"en":"Language is rich with metaphors that shape how we think.","zh-TW":"語言充滿了塑造我們思維方式的隱喻。"}]', '{"adjective":"metaphorical","adverb":"metaphorically"}', NULL, 3, 4250, NULL),
(4251, 'metaphysics', '/ˌmetəˈfɪzɪks/', 'noun', '{"zh-TW":["形而上學"],"en":["the branch of philosophy dealing with the fundamental nature of reality"]}', NULL, 'study metaphysics / philosophy of metaphysics / metaphysics of mind', '[{"en":"Metaphysics examines questions that go beyond physical science.","zh-TW":"形而上學探討超越物理科學的問題。"},{"en":"The debate involves deep questions of metaphysics and ethics.","zh-TW":"這場辯論涉及形而上學和倫理學的深層問題。"}]', '{"adjective":"metaphysical","adverb":"metaphysically"}', NULL, 4, 4251, NULL),
(4252, 'metastasis', '/mɪˈtæstəsɪs/', 'noun', '{"zh-TW":["轉移；癌細胞擴散"],"en":["the spread of cancer from its original site to other parts of the body"]}', NULL, 'prevent metastasis / distant metastasis / metastasis to the liver', '[{"en":"The cancer was caught before metastasis to other organs.","zh-TW":"癌症在轉移到其他器官之前被發現。"},{"en":"Metastasis significantly reduces the chances of a cure.","zh-TW":"轉移顯著降低了治癒的機會。"}]', '{"verb":"metastasize","adjective":"metastatic"}', NULL, 4, 4252, NULL),
(4253, 'metatheory', '/ˈmetəˌθɪəri/', 'noun', '{"zh-TW":["元理論"],"en":["a theory about the nature of theories themselves"]}', NULL, 'develop a metatheory / apply metatheory / metatheory of science', '[{"en":"Metatheory examines the assumptions underlying scientific practice.","zh-TW":"元理論審視科學實踐背後的假設。"},{"en":"A robust metatheory helps researchers choose appropriate methods.","zh-TW":"強健的元理論幫助研究員選擇適當的方法。"}]', '{"adjective":"metatheoretical"}', NULL, 4, 4253, NULL),
(4254, 'methane emissions', '/ˈmiːθeɪn ɪˈmɪʃənz/', 'noun', '{"zh-TW":["甲烷排放"],"en":["the release of methane gas, a potent greenhouse gas, into the atmosphere"]}', NULL, 'reduce methane emissions / methane emissions from livestock / capture methane emissions', '[{"en":"Methane emissions from livestock account for a significant share of agricultural pollution.","zh-TW":"來自牲畜的甲烷排放佔農業污染的重要份額。"},{"en":"Capturing methane emissions from landfills can generate renewable energy.","zh-TW":"捕獲填埋場的甲烷排放可以產生可再生能源。"}]', NULL, NULL, 5, 4254, NULL),
(4255, 'method', '/ˈmeθəd/', 'noun', '{"zh-TW":["方法；辦法"],"en":["a way of doing something systematically"]}', NULL, 'teaching/payment method / method of', '[{"en":"We need to find a more efficient method.","zh-TW":"我們需要找到一種更有效率的方法。"},{"en":"What payment methods do you accept?","zh-TW":"你們接受哪些付款方式？"}]', '{"noun":"method, methodology","adjective":"methodical","adverb":"methodically"}', NULL, 2, 4255, NULL),
(4256, 'methodically', '/''mɪˈθɒdɪkəli/', 'adverb', '{"zh-TW":["有條不紊地；系統地"],"en":["in an orderly and systematic way"]}', NULL, 'work methodically / proceed methodically / organize methodically', '[{"en":"The accountant methodically reviewed each line item in the annual budget.","zh-TW":"會計師有條不紊地審查了年度預算中的每一個項目。"},{"en":"She methodically approached the problem by breaking it down into smaller tasks.","zh-TW":"她通過將問題分解成較小的任務，有條不紊地解決問題。"}]', '{"adjective":"methodical"}', NULL, 4, 4256, NULL),
(4257, 'methodological', '/ˌmeθədəˈlɒdʒɪkəl/', 'adjective', '{"zh-TW":["方法論的"],"en":["relating to the system of methods used in a field"]}', NULL, 'methodological approach / methodological rigor / methodological challenge', '[{"en":"The study''s main contribution is its methodological innovation.","zh-TW":"該研究的主要貢獻是其方法論創新。"},{"en":"Methodological flaws can undermine even the best research questions.","zh-TW":"方法論缺陷可能破壞即使是最好的研究問題。"}]', '{"noun":"methodology","adverb":"methodologically"}', NULL, 5, 4257, NULL),
(4258, 'methodology', '/ˌmɛθəˈdɒlədʒi/', 'noun', '{"zh-TW":["方法論"],"en":["a system of methods used in a particular area"]}', NULL, 'research methodology / agile methodology', '[{"en":"We follow agile methodology in development.","zh-TW":"我們在開發中遵循敏捷方法論。"},{"en":"The research methodology is clearly defined.","zh-TW":"研究方法論有明確的定義。"},{"en":"The company adopted an agile methodology for software development.","zh-TW":"公司採用了敏捷方法論進行軟體開發。"},{"en":"Please describe the methodology used in your study.","zh-TW":"請描述你研究中使用的方法論。"}]', '{"noun":"methodology","adjective":"methodological","adverb":"methodologically"}', NULL, 4, 4258, NULL),
(4259, 'meticulous', '/mɪˈtɪkjələs/', 'adjective', '{"zh-TW":["一絲不苟的；極其仔細的"],"en":["showing great attention to detail"]}', NULL, 'meticulous attention to detail / meticulous planning', '[{"en":"She is meticulous in her work and rarely makes errors.","zh-TW":"她工作一絲不苟，很少犯錯。"},{"en":"Meticulous planning ensured the event''s success.","zh-TW":"細緻的規劃確保了活動的成功。"}]', '{"adjective":"meticulous","adverb":"meticulously"}', NULL, 4, 4259, NULL),
(4260, 'metrics', 'ˈmɛtrɪks', 'noun', '{"zh-TW":["指標；度量","衡量標準"],"en":["measures used to evaluate performance","data points"]}', NULL, 'key metrics/track metrics', '[{"en":"Monitor these key performance metrics.","zh-TW":"監控這些關鍵績效指標。"}]', '{"adjective":"metric"}', NULL, 3, 4260, NULL),
(4261, 'mezzanine', '/ˈmezəniːn/', 'noun', '{"zh-TW":["夾層融資；中間層"],"en":["an intermediate layer of financing between senior debt and equity"]}', NULL, 'mezzanine financing / mezzanine debt / mezzanine tranche', '[{"en":"Mezzanine financing bridges the gap between debt and equity.","zh-TW":"夾層融資填補了債務和股權之間的差距。"},{"en":"The deal''s mezzanine tranche carried a higher interest rate.","zh-TW":"該交易的夾層部分帶有更高的利率。"}]', '{"adjective":"mezzanine"}', NULL, 3, 4261, NULL),
(4262, 'microeconomics', '/ˌmaɪkroʊˌiːkəˈnɒmɪks/', 'noun', '{"zh-TW":["微觀經濟學"],"en":["the study of individual economic behaviors and decisions"]}', NULL, 'apply microeconomics / microeconomics principles', '[{"en":"Microeconomics helps predict how consumers respond to price changes.","zh-TW":"微觀經濟學有助於預測消費者如何應對價格變化。"},{"en":"Understanding microeconomics is valuable for pricing and market analysis.","zh-TW":"了解微觀經濟學對定價和市場分析很有價值。"}]', NULL, NULL, 5, 4262, NULL),
(4263, 'microfinance', '/ˈmaɪkrəʊˌfaɪnæns/', 'noun', '{"zh-TW":["微型金融；小額信貸"],"en":["the provision of small financial services to low-income individuals or businesses"]}', NULL, 'microfinance institution / provide microfinance / microfinance program', '[{"en":"Microfinance loans helped women entrepreneurs in developing countries start businesses.","zh-TW":"小額信貸幫助發展中國家的女性企業家創辦了企業。"},{"en":"Microfinance programs have improved financial inclusion in rural communities.","zh-TW":"微型金融計畫改善了農村社區的金融普惠性。"}]', '{"adjective":"microfinancial"}', NULL, 4, 4263, NULL),
(4264, 'micromanage', '/ˈmaɪkroʊˌmænɪdʒ/', 'verb', '{"zh-TW":["過度管理；微觀管理"],"en":["to control every small detail of a task or person''s work"]}', NULL, 'avoid micromanaging / tendency to micromanage', '[{"en":"Micromanaging reduces employee autonomy and creativity.","zh-TW":"過度管理降低了員工的自主性和創造力。"},{"en":"Trust your team and avoid the urge to micromanage.","zh-TW":"信任你的團隊，避免過度管理的衝動。"}]', '{"noun":"micromanager","adjective":"micromanaged"}', NULL, 4, 4264, NULL),
(4265, 'micronutrient', '/''maɪkrəʊˌnjuːtriənt/', 'noun', '{"zh-TW":["微量營養素"],"en":["a vitamin or mineral required in small amounts but essential for health"]}', NULL, 'micronutrient deficiency / provide micronutrients / essential micronutrient', '[{"en":"Iron and vitamin D are common micronutrients that many people lack.","zh-TW":"鐵和維生素D是許多人缺乏的常見微量營養素。"},{"en":"A varied diet is the best way to ensure adequate micronutrient intake.","zh-TW":"多樣化的飲食是確保充足微量營養素攝取的最佳方式。"}]', NULL, NULL, 5, 4265, NULL),
(4266, 'microplastics', '/ˈmaɪkrəʊˌplæstɪks/', 'noun', '{"zh-TW":["微塑料"],"en":["tiny plastic particles less than five millimetres in size contaminating environments"]}', NULL, 'microplastics pollution / microplastics in the ocean / filter microplastics', '[{"en":"Microplastics have been found in human blood and ocean fish.","zh-TW":"在人類血液和海洋魚類中發現了微塑料。"},{"en":"Reducing single-use plastics is essential to combat microplastics pollution.","zh-TW":"減少一次性塑料對於應對微塑料污染至關重要。"}]', NULL, NULL, 5, 4266, NULL),
(4267, 'microservices', '/ˈmaɪkrəʊˌsɜːrvɪsɪz/', 'noun', '{"zh-TW":["微服務"],"en":["an architectural approach building software as small, independent services"]}', NULL, 'adopt microservices / microservices architecture / decompose into microservices', '[{"en":"Microservices allow teams to deploy and scale individual components independently.","zh-TW":"微服務允許團隊獨立部署和擴展各個組件。"},{"en":"The monolithic application was refactored into microservices over two years.","zh-TW":"單體應用程式花了兩年時間重構為微服務。"}]', NULL, NULL, 5, 4267, NULL),
(4268, 'mid-year review', '/ˌmɪd jɪər rɪˈvjuː/', 'noun', '{"zh-TW":["中期審查；半年回顧"],"en":["a review of performance conducted halfway through a fiscal year"]}', NULL, 'conduct a mid-year review / mid-year review process', '[{"en":"The mid-year review identified the need to reforecast revenue.","zh-TW":"中期審查識別了需要重新預測收入的必要性。"},{"en":"Mid-year reviews allow management to adjust strategies if needed.","zh-TW":"中期審查允許管理層在需要時調整策略。"}]', NULL, NULL, 5, 4268, NULL),
(4269, 'middle', '/ˈmɪdəl/', 'noun', '{"zh-TW":["中間；中部"],"en":["the central point or position"]}', NULL, 'middle management / in the middle of', '[{"en":"She is in middle management.","zh-TW":"她是中層管理人員。"},{"en":"We are in the middle of negotiations.","zh-TW":"我們正在談判中。"}]', '{"noun":"middle","adjective":"middle"}', NULL, 2, 4269, NULL),
(4270, 'middle seat', '/''mɪdəl siːt/', 'noun', '{"zh-TW":["中間座位"],"en":["the seat between the window seat and the aisle seat in an aircraft row"]}', NULL, 'stuck in the middle seat / avoid the middle seat', '[{"en":"Nobody likes the middle seat because it has no window or easy aisle access.","zh-TW":"沒有人喜歡中間座位，因為它沒有窗戶，也不方便進入走道。"},{"en":"She arrived late and was assigned the middle seat at the back of the plane.","zh-TW":"她到得很晚，被分配到飛機後部的中間座位。"}]', NULL, NULL, 4, 4270, NULL),
(4271, 'middleware', '/ˈmɪdəlweər/', 'noun', '{"zh-TW":["中間件"],"en":["software that connects different applications or components in a network"]}', NULL, 'integrate middleware / middleware layer / message middleware', '[{"en":"Middleware handles communication between the frontend and backend systems.","zh-TW":"中間件處理前端和後端系統之間的通信。"},{"en":"API gateways and message brokers are common forms of middleware.","zh-TW":"API閘道和訊息代理是常見的中間件形式。"}]', NULL, NULL, 4, 4271, NULL),
(4272, 'midterm', '/ˈmɪdtɜːrm/', 'noun', '{"zh-TW":["期中考"],"en":["an exam in the middle of a term"]}', NULL, 'midterm exam / midterm grades', '[{"en":"I''m studying for my midterms.","zh-TW":"我正在準備期中考。"},{"en":"Midterm grades will be posted Friday.","zh-TW":"期中成績將在週五公布。"}]', NULL, NULL, 3, 4272, NULL),
(4273, 'migrate', '/ˈmaɪɡreɪt/', 'verb', '{"zh-TW":["遷移；移民"],"en":["to move from one place to another"]}', NULL, 'migrate to / migrate data/systems', '[{"en":"Many companies are migrating their data to the cloud.","zh-TW":"許多公司正在將數據遷移到雲端。"},{"en":"Birds migrate south for the winter.","zh-TW":"鳥類冬天遷徙到南方。"}]', '{"noun":"migration, migrant","verb":"migrate","adjective":"migratory"}', NULL, 3, 4273, NULL),
(4274, 'migration', '/maɪˈɡreɪʃən/', 'noun', '{"zh-TW":["數據遷移；系統遷移"],"en":["the process of moving data or systems from one platform to another"]}', NULL, 'data migration / system migration / cloud migration / migration plan', '[{"en":"The cloud migration reduced infrastructure costs by 40%.","zh-TW":"雲端遷移將基礎設施成本降低了40%。"},{"en":"A data migration plan was developed to ensure zero data loss.","zh-TW":"制定了數據遷移計劃以確保零數據遺失。"}]', '{"verb":"migrate","adjective":"migrated"}', NULL, 3, 4274, NULL),
(4275, 'mileage reward', '/''maɪlɪdʒ rɪˈwɔːrd/', 'noun', '{"zh-TW":["里程獎勵；飛行里程獎勵"],"en":["points or miles earned through airline travel that can be redeemed for flights or upgrades"]}', NULL, 'earn mileage rewards / redeem mileage rewards / accumulate mileage', '[{"en":"She used her accumulated mileage rewards to book a free business class ticket.","zh-TW":"她使用累積的里程獎勵預訂了免費的商務艙機票。"},{"en":"Enrolling in a mileage reward program is worthwhile if you travel frequently.","zh-TW":"如果你經常旅行，加入里程獎勵計畫是值得的。"}]', NULL, NULL, 5, 4275, NULL),
(4276, 'milestone', '/ˈmaɪlstoʊn/', 'noun', '{"zh-TW":["里程碑；重要事件"],"en":["an important event in the development of something"]}', NULL, 'reach/achieve a milestone / project milestone', '[{"en":"Reaching 1 million users was a major milestone.","zh-TW":"達到100萬用戶是一個重要的里程碑。"},{"en":"The project has several key milestones to meet.","zh-TW":"該項目有幾個關鍵里程碑需要完成。"}]', '{"noun":"milestone"}', NULL, 3, 4276, 890),
(4277, 'milestone payment', '/ˈmaɪlstoʊn ˈpeɪmənt/', 'noun', '{"zh-TW":["里程碑付款"],"en":["a payment made upon achieving a specific project milestone"]}', NULL, 'agree on milestone payments / trigger a milestone payment', '[{"en":"Milestone payments ensure the contractor is paid progressively.","zh-TW":"里程碑付款確保了承包商按進度獲得報酬。"},{"en":"The project contract includes four milestone payments tied to deliverables.","zh-TW":"項目合約包含與可交付成果掛鈎的四項里程碑付款。"}]', NULL, NULL, 5, 4277, NULL),
(4278, 'milestone review', '/ˈmaɪlstoʊn rɪˈvjuː/', 'noun', '{"zh-TW":["里程碑審查"],"en":["a formal check at a defined project stage to assess progress and authorize continuation"]}', NULL, 'conduct a milestone review / pass the milestone review', '[{"en":"The steering committee approved the project to continue after the milestone review.","zh-TW":"指導委員會在里程碑審查後批准了項目繼續進行。"},{"en":"A milestone review ensures the project is on track before releasing more funds.","zh-TW":"里程碑審查確保在釋放更多資金前項目處於正軌。"}]', NULL, NULL, 5, 4278, NULL),
(4279, 'milk', '/mɪlk/', 'noun', '{"zh-TW":["牛奶"],"en":["a white liquid from cows"]}', NULL, 'milk products / don''t cry over spilled milk', '[{"en":"The cafeteria offers various milk products.","zh-TW":"自助餐廳提供各種乳製品。"},{"en":"Don''t cry over spilled milk; move forward.","zh-TW":"不要為打翻的牛奶哭泣；向前看。"}]', '{"noun":"milk","adjective":"milky","verb":"milk"}', NULL, 1, 4279, NULL),
(4280, 'million', 'ˈmɪljən', 'noun', '{"zh-TW":["百萬","大量"],"en":["a thousand thousand","an extremely large number"]}', NULL, 'one million/million-dollar', '[{"en":"The company earned five million in revenue.","zh-TW":"公司賺了五百萬的收入。"}]', '{"adjective":"million-dollar"}', NULL, 3, 4280, NULL),
(4281, 'mind', '/maɪnd/', 'noun', '{"zh-TW":["【主要意義-名詞】心智；思想；意見","【次要意義-動詞】照料；看管","【次要意義-動詞】介意；在乎","【次要意義-動詞】注意；小心（命令句）"],"en":["[primary - noun] the part of a person that thinks and feels","[secondary - verb] to look after or take care of something","[secondary - verb] to feel bothered or annoyed by something","[secondary - verb] to be careful about something (in imperatives)"]}', NULL, 'mind the gap / bear in mind / never mind / mind your own business / mind the store', '[{"en":"Could you mind the front desk while I attend the meeting?","zh-TW":"我去參加會議時，你能照看前台嗎？"},{"en":"Bear in mind that all expenses must be approved before submission.","zh-TW":"請記住，所有費用必須在提交前獲得批准。"},{"en":"Do you mind if I reschedule our appointment to next Tuesday?","zh-TW":"您介意將我們的預約改到下週二嗎？"}]', '{"adjective":"mindful, mindless","noun":"mindset"}', '動詞 mind = 「照料」（mind the store = 看顧業務），bear in mind（記住），do you mind if（您介意嗎？）均是 TOEIC 高頻職場用語，考生常誤以為 mind 只是名詞「心智」。', 1, 4281, NULL),
(4282, 'mindfulness', '/''maɪndfʊlnəs/', 'noun', '{"zh-TW":["正念；當下覺察"],"en":["a mental state of being conscious and aware, focusing on the present moment without judgment"]}', NULL, 'practice mindfulness / mindfulness meditation / benefit of mindfulness', '[{"en":"Practicing mindfulness for just ten minutes daily can reduce stress significantly.","zh-TW":"每天僅練習十分鐘正念就能顯著降低壓力。"},{"en":"Many corporations now offer mindfulness programs to improve employee well-being.","zh-TW":"許多企業現在提供正念計劃，以改善員工的健康。"}]', '{"adjective":"mindful","adverb":"mindfully"}', NULL, 4, 4282, NULL),
(4283, 'mindset', 'ˈmaɪndˌsɛt', 'noun', '{"zh-TW":["心態；思維方式","觀念"],"en":["an established set of attitudes","a way of thinking"]}', NULL, 'growth mindset/positive mindset', '[{"en":"Cultivate a growth mindset.","zh-TW":"培養成長型心態。"}]', NULL, NULL, 3, 4283, NULL),
(4284, 'mineral', '/ˈmɪnərəl/', 'noun, adjective', '{"zh-TW":["礦物；礦產"],"en":["a natural substance found in the earth"]}', NULL, 'mineral resources/deposits/water', '[{"en":"The country is rich in mineral resources.","zh-TW":"該國礦產資源豐富。"},{"en":"Mineral water is available at the front desk.","zh-TW":"前台有提供礦泉水。"}]', '{"noun":"mineral, mining","adjective":"mineral"}', NULL, 3, 4284, NULL),
(4285, 'minibar', '/ˈmɪnibɑːr/', 'noun', '{"zh-TW":["迷你吧；小型冰箱"],"en":["a small refrigerator stocked with drinks in a hotel room"]}', NULL, 'use the minibar / minibar charges', '[{"en":"The minibar is stocked with soft drinks and snacks.","zh-TW":"迷你吧備有軟性飲料和零食。"},{"en":"Minibar charges will appear on your bill.","zh-TW":"迷你吧費用將計入您的帳單。"}]', NULL, NULL, 3, 4285, NULL),
(4286, 'minimalism', '/ˈmɪnɪməlɪzəm/', 'noun', '{"zh-TW":["極簡主義"],"en":["a style or technique characterized by extreme spareness"]}', NULL, 'academic minimalism / design minimalism / apply minimalism', '[{"en":"Minimalism in academic writing means eliminating everything unnecessary.","zh-TW":"學術寫作中的極簡主義意味著消除所有不必要的內容。"},{"en":"Many modern apps adopt minimalism to improve user experience.","zh-TW":"許多現代應用程式採用極簡主義來改善用戶體驗。"}]', '{"adjective":"minimalist","adverb":"minimalistically"}', NULL, 4, 4286, NULL),
(4287, 'minimize', '/ˈmɪnɪmaɪz/', 'verb', '{"zh-TW":["最小化；減少"],"en":["to reduce to the smallest possible amount"]}', NULL, 'minimize risk/cost/damage', '[{"en":"We must minimize the risk of data loss.","zh-TW":"我們必須將數據丟失的風險降到最低。"},{"en":"The new procedure minimizes waste.","zh-TW":"新程序將浪費減到最少。"}]', '{"noun":"minimum","verb":"minimize","adjective":"minimum, minimal"}', NULL, 3, 4287, 157),
(4288, 'minimum', 'ˈmɪnɪməm', 'noun', '{"zh-TW":["最小值；最低限度","最少量"],"en":["the least possible amount","a lower limit"]}', NULL, 'minimum wage/at a minimum', '[{"en":"The minimum order is 100 units.","zh-TW":"最低訂購量為100件。"}]', '{"adjective":"minimum","adverb":"minimally"}', NULL, 3, 4288, 395),
(4289, 'minimum order quantity', '/ˈmɪnɪməm ˈɔːrdər ˈkwɒntɪti/', 'noun', '{"zh-TW":["最小訂購量"],"en":["the smallest amount a supplier requires to fulfill an order"]}', NULL, 'meet the minimum order quantity / negotiate minimum order quantity', '[{"en":"The supplier requires a minimum order quantity of 500 units.","zh-TW":"供應商要求最小訂購量為500件。"},{"en":"The startup struggled to meet the minimum order quantity.","zh-TW":"新創公司難以達到最小訂購量。"}]', '{"abbreviation":"MOQ"}', NULL, 5, 4289, NULL),
(4290, 'minimum viable product', '/ˈmɪnɪməm ˈvaɪəbl ˈprɒdʌkt/', 'noun', '{"zh-TW":["最小可行產品"],"en":["a version of a product with just enough features to satisfy early customers"]}', NULL, 'launch an MVP / build an MVP / MVP feedback', '[{"en":"The startup launched an MVP to validate the market before full development.","zh-TW":"新創公司在全面開發前推出最小可行產品以驗證市場。"},{"en":"An MVP allows rapid learning with minimal investment.","zh-TW":"最小可行產品允許以最少投資快速學習。"}]', '{"abbreviation":"MVP"}', NULL, 5, 4290, NULL),
(4291, 'minimum wage', '/ˈmɪnɪməm weɪdʒ/', 'noun', '{"zh-TW":["最低薪資"],"en":["the lowest hourly or monthly rate employers are legally required to pay workers"]}', NULL, 'comply with minimum wage / raise the minimum wage', '[{"en":"The government raised the minimum wage for the third consecutive year.","zh-TW":"政府連續第三年提高了最低薪資。"},{"en":"Paying above minimum wage helps companies attract better candidates.","zh-TW":"支付高於最低薪資有助於公司吸引更好的候選人。"}]', NULL, NULL, 4, 4291, NULL),
(4292, 'ministry', '/ˈmɪnɪstri/', 'noun', '{"zh-TW":["部；部門（政府）"],"en":["a government department led by a minister"]}', NULL, 'Ministry of Finance/Education/Health', '[{"en":"The Ministry of Finance released the annual budget.","zh-TW":"財政部發布了年度預算。"},{"en":"She works at the Ministry of Education.","zh-TW":"她在教育部工作。"}]', '{"noun":"ministry, minister","adjective":"ministerial"}', NULL, 3, 4292, NULL),
(4293, 'minor', '/ˈmaɪnər/', 'adjective, noun', '{"zh-TW":["次要的；較小的","未成年人"],"en":["not very important; smaller","a person under the legal age"]}', NULL, 'minor issue/problem/change', '[{"en":"It''s only a minor issue and can be fixed quickly.","zh-TW":"這只是一個小問題，可以很快解決。"},{"en":"There were a few minor adjustments to the schedule.","zh-TW":"行程有一些小的調整。"}]', '{"noun":"minor, minority","adjective":"minor"}', NULL, 2, 4293, NULL),
(4294, 'minority interest', '/maɪˈnɒrɪti ˈɪntrəst/', 'noun', '{"zh-TW":["少數股東權益"],"en":["the portion of a subsidiary not owned by the parent company"]}', NULL, 'disclose minority interest / minority interest holders', '[{"en":"The consolidated accounts include minority interest from the joint venture.","zh-TW":"合並帳目包括來自合資企業的少數股東權益。"},{"en":"Minority interest shareholders received a proportionate dividend.","zh-TW":"少數股東權益持有人獲得了按比例的股息。"}]', NULL, NULL, 5, 4294, NULL),
(4295, 'minority stake', '/maɪˈnɒrɪti steɪk/', 'noun', '{"zh-TW":["少數股份"],"en":["an ownership interest of less than 50% in a company"]}', NULL, 'acquire a minority stake / sell a minority stake', '[{"en":"The fund acquired a 20% minority stake in the startup.","zh-TW":"基金在新創公司中收購了20%的少數股份。"},{"en":"A minority stake can provide influence without full control.","zh-TW":"少數股份可以在沒有完全控制的情況下提供影響力。"}]', NULL, NULL, 5, 4295, NULL),
(4296, 'minute', '/maɪˈnjuːt/', 'adjective', '{"zh-TW":["【主要意義-名詞】分鐘","【次要意義-形容詞】微小的；極細緻的；極詳盡的（重音在第二音節）","【次要意義-複數名詞】會議記錄（minutes）"],"en":["[primary - noun] a unit of time (60 seconds)","[secondary - adjective] extremely small or detailed (stress on second syllable: /maɪˈnjuːt/)","[secondary - plural noun] the official written record of a meeting"]}', NULL, 'minute details / minute examination / take the minutes / approve the minutes', '[{"en":"The inspector carried out a minute examination of the document.","zh-TW":"檢查員對該文件進行了極為詳細的審查。"},{"en":"Could you take the minutes at today''s board meeting?","zh-TW":"你能記錄今天董事會議的會議記錄嗎？"},{"en":"The difference between the two samples was minute but significant.","zh-TW":"兩個樣本之間的差異微乎其微但卻意義重大。"}]', '{"adverb":"minutely","noun":"minuteness"}', 'minute 作形容詞時重音移至第二音節，意為「微小的」；複數 minutes 意為「會議記錄」，兩者都是 TOEIC 高頻陷阱字。', 2, 4296, NULL),
(4297, 'minutes', '/ˈmɪnɪts/', 'noun', '{"zh-TW":["會議記錄"],"en":["an official written record of what was discussed in a meeting"]}', NULL, 'take the minutes / circulate the minutes / approve the minutes', '[{"en":"She was asked to take the minutes during the board meeting.","zh-TW":"她被要求在董事會會議期間記錄會議記錄。"},{"en":"The minutes were approved at the start of the next meeting.","zh-TW":"會議記錄在下次會議開始時獲得批准。"}]', NULL, NULL, 3, 4297, NULL),
(4298, 'minutes of meeting', '/ˈmɪnɪts əv ˈmiːtɪŋ/', 'noun', '{"zh-TW":["會議記錄"],"en":["an official written record of a meeting"]}', NULL, 'circulate minutes of meeting / approve minutes of meeting', '[{"en":"The secretary circulated the minutes of meeting to all attendees.","zh-TW":"秘書將會議記錄發送給所有與會者。"},{"en":"Please review and approve the minutes of last week''s meeting.","zh-TW":"請查看並批准上週的會議記錄。"}]', NULL, NULL, 5, 4298, NULL),
(4299, 'miscellaneous expenses', '/ˌmɪsəˈleɪniəs ɪkˈspensɪz/', 'noun', '{"zh-TW":["雜項費用"],"en":["small or unplanned costs that do not fit into a specific expense category"]}', NULL, 'account for miscellaneous expenses / miscellaneous expenses budget', '[{"en":"Miscellaneous expenses were tracked separately in the expense report.","zh-TW":"雜項費用在費用報告中被單獨追蹤。"},{"en":"A budget line for miscellaneous expenses prevents overruns.","zh-TW":"雜項費用的預算項目可防止超支。"}]', NULL, NULL, 5, 4299, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(4300, 'miscommunication', '/''mɪskəˌmjuːnɪˈkeɪʃən/', 'noun', '{"zh-TW":["溝通不良；誤解"],"en":["a failure to communicate clearly, resulting in misunderstanding"]}', NULL, 'cause miscommunication / avoid miscommunication / result of miscommunication', '[{"en":"The project delay was caused by miscommunication between the client and the development team.","zh-TW":"項目延誤是由客戶和開發團隊之間的溝通不良造成的。"},{"en":"Regular team meetings help prevent miscommunication about goals and responsibilities.","zh-TW":"定期的團隊會議有助於防止關於目標和責任的溝通不良。"}]', '{"verb":"miscommunicate"}', NULL, 5, 4300, NULL),
(4301, 'misconduct', '/ˌmɪsˈkɑːndʌkt/', 'noun', '{"zh-TW":["不當行為；瀆職"],"en":["unacceptable or improper behavior, especially by a professional"]}', NULL, 'professional/employee misconduct / allegations of misconduct', '[{"en":"He was fired for gross misconduct.","zh-TW":"他因嚴重不當行為被解僱。"},{"en":"The investigation found evidence of financial misconduct.","zh-TW":"調查發現了財務不當行為的證據。"}]', '{"noun":"misconduct"}', NULL, 4, 4301, NULL),
(4302, 'mise en place', '/''miːz ɒn plɑːs/', 'noun', '{"zh-TW":["廚房備料；一切就緒"],"en":["a French culinary concept meaning ''everything in its place''; the preparation and organization of ingredients before cooking"]}', NULL, 'practice mise en place / mise en place technique / good mise en place', '[{"en":"Professional chefs use mise en place to ensure smooth and efficient cooking.","zh-TW":"專業廚師使用廚房備料確保烹飪順暢高效。"},{"en":"Preparing your mise en place before you start cooking reduces stress and mistakes.","zh-TW":"在開始烹飪之前準備好所有食材可以減少壓力和錯誤。"}]', NULL, NULL, 5, 4302, NULL),
(4303, 'misinformation', '/''mɪsɪnfəˌmeɪʃən/', 'noun', '{"zh-TW":["錯誤訊息；謊言"],"en":["false or inaccurate information, especially that which is deliberately intended to deceive"]}', NULL, 'spread misinformation / combat misinformation / misinformation campaign', '[{"en":"Social media platforms are working to reduce the spread of misinformation.","zh-TW":"社交媒體平台正在努力減少錯誤訊息的傳播。"},{"en":"Educators teach students how to identify and avoid misinformation online.","zh-TW":"教育工作者教學生如何識別和避免網絡上的錯誤訊息。"}]', '{"noun2":"misinformer","verb":"misinform"}', NULL, 5, 4303, NULL),
(4304, 'mislead', '/ˌmɪsˈliːd/', 'verb', '{"zh-TW":["誤導；使產生錯誤印象"],"en":["to cause someone to have a wrong impression"]}', NULL, 'mislead consumers/investors / misleading information', '[{"en":"The advertisement was found to mislead consumers.","zh-TW":"該廣告被發現誤導消費者。"},{"en":"Don''t be misled by the low price.","zh-TW":"不要被低價格所誤導。"}]', '{"verb":"mislead","adjective":"misleading"}', NULL, 3, 4304, NULL),
(4305, 'miss', '/mɪs/', 'verb', '{"zh-TW":["錯過；想念"],"en":["to fail to attend or catch","to feel sad about absence"]}', NULL, 'miss the point / miss a deadline', '[{"en":"We cannot miss this opportunity.","zh-TW":"我們不能錯過這個機會。"},{"en":"Don''t miss the deadline.","zh-TW":"別錯過截止日期。"}]', '{"verb":"miss","adjective":"missing","noun":"miss"}', NULL, 1, 4305, NULL),
(4306, 'mission', 'ˈmɪʃən', 'noun', '{"zh-TW":["使命；任務","宗旨"],"en":["a purpose or goal","a duty assigned"]}', NULL, 'company mission/mission statement', '[{"en":"Our mission is to serve customers globally.","zh-TW":"我們的使命是在全球服務客戶。"}]', '{"adjective":"mission-driven"}', NULL, 3, 4306, 158),
(4307, 'mission statement', '/ˈmɪʃən ˌsteɪtmənt/', 'noun', '{"zh-TW":["使命宣言"],"en":["a formal statement of a company''s purpose and objectives"]}', NULL, 'write a mission statement / company mission statement', '[{"en":"The mission statement guides all strategic decisions.","zh-TW":"使命宣言指導所有策略決策。"},{"en":"They revised the mission statement to reflect new goals.","zh-TW":"他們修訂了使命宣言以反映新目標。"}]', NULL, NULL, 5, 4307, NULL),
(4308, 'mistake', '/mɪˈsteɪk/', 'noun', '{"zh-TW":["錯誤"],"en":["something done incorrectly"]}', NULL, 'make a mistake / by mistake', '[{"en":"Everyone makes mistakes sometimes.","zh-TW":"每個人有時都會犯錯。"},{"en":"I sent the email by mistake.","zh-TW":"我不小心寄了那封郵件。"}]', '{"noun":"mistake","verb":"mistake","adjective":"mistaken"}', NULL, 3, 4308, NULL),
(4309, 'misunderstand', '/ˌmɪsʌndərˈstænd/', 'verb', '{"zh-TW":["誤解；誤會"],"en":["to fail to understand correctly"]}', NULL, 'misunderstand instructions/intentions', '[{"en":"I think you misunderstood my intentions.","zh-TW":"我想你誤解了我的意思。"},{"en":"The email was misunderstood by several recipients.","zh-TW":"這封電子郵件被幾位收件者誤解了。"}]', '{"noun":"misunderstanding","verb":"misunderstand"}', NULL, 5, 4309, NULL),
(4310, 'mitigate', '/ˈmɪtɪɡeɪt/', 'verb', '{"zh-TW":["減輕；緩和"],"en":["to make something less severe or harmful"]}', NULL, 'mitigate risk/damage/effects', '[{"en":"Steps were taken to mitigate the environmental impact.","zh-TW":"已採取措施減輕環境影響。"},{"en":"Insurance can help mitigate financial risk.","zh-TW":"保險可以幫助減輕財務風險。"}]', '{"noun":"mitigation","verb":"mitigate","adjective":"mitigating"}', NULL, 3, 4310, 698),
(4311, 'mitigation', '/ˌmɪtɪˈɡeɪʃən/', 'noun', '{"zh-TW":["緩解；減輕"],"en":["actions taken to reduce the severity of a risk or problem"]}', NULL, 'risk mitigation / mitigation measures / mitigation strategy', '[{"en":"The project team developed mitigation measures for identified risks.","zh-TW":"項目團隊為識別的風險制定了緩解措施。"},{"en":"Mitigation efforts reduced the financial impact of the disruption.","zh-TW":"緩解工作降低了中斷的財務影響。"}]', '{"verb":"mitigate","adjective":"mitigated"}', NULL, 4, 4311, 892),
(4312, 'mix', '/mɪks/', 'verb', '{"zh-TW":["混合"],"en":["to combine different things together"]}', NULL, 'product mix / mix up', '[{"en":"We need a better product mix.","zh-TW":"我們需要更好的產品組合。"},{"en":"There was a mix-up with the orders.","zh-TW":"訂單搞混了。"}]', '{"verb":"mix","noun":"mix","noun2":"mixture","noun3":"mix-up"}', NULL, 1, 4312, NULL),
(4313, 'mixed-use development', '/''mɪkst juːs dɪˌveləpmənt/', 'noun', '{"zh-TW":["混合用途開發；綜合用途發展"],"en":["a type of urban development that combines residential, commercial, and sometimes industrial uses"]}', NULL, 'plan a mixed-use development / mixed-use development project / benefit of mixed-use development', '[{"en":"Mixed-use developments create vibrant neighborhoods by placing housing, shops, and offices together.","zh-TW":"混合用途開發通過將住宅、商店和辦公室集中在一起，創造充滿活力的社區。"},{"en":"The city approved a mixed-use development that includes apartments, retail space, and a park.","zh-TW":"市政府批准了一個包含公寓、零售空間和公園的混合用途開發項目。"}]', '{"adjective":"mixed-use"}', NULL, 5, 4313, NULL),
(4314, 'mobile', '/ˈmoʊbl/', 'adjective, noun', '{"zh-TW":["移動的；手機的","行動電話"],"en":["able to move easily; relating to cell phones","a cell phone"]}', NULL, 'mobile device/app/phone / mobile banking', '[{"en":"Mobile banking has become increasingly popular.","zh-TW":"行動銀行越來越受歡迎。"},{"en":"More users access the site via mobile devices.","zh-TW":"越來越多用戶通過行動裝置訪問網站。"}]', '{"noun":"mobile, mobility","adjective":"mobile","verb":"mobilize"}', NULL, 2, 4314, NULL),
(4315, 'mobile check-in', '/ˈməʊbaɪl ˈtʃɛkɪn/', 'noun', '{"zh-TW":["手機報到"],"en":["the process of checking in using a smartphone"]}', NULL, 'use mobile check-in / mobile check-in option', '[{"en":"Mobile check-in saves time at the airport.","zh-TW":"手機報到可以節省在機場的時間。"},{"en":"Download the airline app to use mobile check-in.","zh-TW":"下載航空公司應用程式以使用手機報到。"}]', NULL, NULL, 5, 4315, NULL),
(4316, 'mobility', '/moʊˈbɪləti/', 'noun', '{"zh-TW":["流動性；移動性"],"en":["the ability to move freely; social advancement"]}', NULL, 'social/career mobility / labor mobility', '[{"en":"Career mobility is important to today''s workforce.","zh-TW":"職業流動性對當今勞動力很重要。"},{"en":"The new policy promotes upward social mobility.","zh-TW":"新政策促進了社會向上流動。"}]', '{"noun":"mobility, mobile","adjective":"mobile","verb":"mobilize"}', NULL, 3, 4316, NULL),
(4317, 'mobilize', '/ˈmoʊbɪlaɪz/', 'verb', '{"zh-TW":["動員；調動"],"en":["to organize resources or people for a specific purpose or action"]}', NULL, 'mobilize resources / mobilize a team', '[{"en":"The project manager mobilized the team quickly after contract signing.","zh-TW":"合約簽署後，項目經理迅速動員了團隊。"},{"en":"The government mobilized emergency funds to address the crisis.","zh-TW":"政府調動了緊急資金應對危機。"}]', '{"noun":"mobilization","adjective":"mobilized"}', NULL, 3, 4317, 699),
(4318, 'model drift', '/ˈmɒdəl drɪft/', 'noun', '{"zh-TW":["模型漂移"],"en":["the degradation of model performance over time as real-world data changes"]}', NULL, 'detect model drift / model drift monitoring / address model drift', '[{"en":"Model drift occurs when real-world patterns diverge from training data.","zh-TW":"當現實世界的模式與訓練數據分歧時，模型漂移就會發生。"},{"en":"Automated monitoring systems alert teams when model drift is detected.","zh-TW":"自動監控系統在檢測到模型漂移時提醒團隊。"}]', NULL, NULL, 4, 4318, NULL),
(4319, 'model portfolio', '/ˈmɒdəl pɔːrtˈfoʊlioʊ/', 'noun', '{"zh-TW":["示範投資組合；模型組合"],"en":["a pre-designed investment portfolio serving as a benchmark or recommendation"]}', NULL, 'follow a model portfolio / build a model portfolio', '[{"en":"The advisor presented a model portfolio aligned to a moderate risk profile.","zh-TW":"顧問展示了符合適中風險偏好的示範投資組合。"},{"en":"Model portfolios simplify investment decisions for retail clients.","zh-TW":"示範投資組合簡化了零售客戶的投資決策。"}]', NULL, NULL, 5, 4319, NULL),
(4320, 'moderate', '/ˈmɑːdərət/', 'adjective, verb', '{"zh-TW":["適度的；中等的","調節；緩和"],"en":["average in amount; not extreme","to make less extreme"]}', NULL, 'moderate growth/risk/climate', '[{"en":"The company experienced moderate growth this year.","zh-TW":"公司今年經歷了適度的增長。"},{"en":"The chairman moderated the discussion.","zh-TW":"主席主持了討論。"}]', '{"noun":"moderation, moderator","adjective":"moderate","verb":"moderate","adverb":"moderately"}', NULL, 3, 4320, 700),
(4321, 'modern', '/ˈmɒdərn/', 'adjective', '{"zh-TW":["現代的"],"en":["relating to the present time"]}', NULL, 'modern technology / modern design', '[{"en":"The office has a modern design.","zh-TW":"辦公室採用了現代設計。"},{"en":"Modern technology makes work easier.","zh-TW":"現代科技使工作更容易。"}]', '{"adjective":"modern","verb":"modernize","noun":"modernity","noun2":"modernization"}', NULL, 2, 4321, NULL),
(4322, 'modest', '/ˈmɒdɪst/', 'adjective', '{"zh-TW":["謙虛的；適度的"],"en":["unassuming in attitude","relatively moderate or small"]}', '{"root":{"text":"mod","meaning":"measure (適度)"},"suffix":{"text":"-est","meaning":"most (最)"},"logic":"保持適度的，即「謙虛的」。"}', 'modest income / modest improvement', '[{"en":"She is modest about her achievements.","zh-TW":"她對自己的成就很謙虛。"},{"en":"They live in a modest apartment.","zh-TW":"他們住在一間簡樸的公寓。"}]', '{"noun":"modesty","adverb":"modestly"}', NULL, 2, 4322, NULL),
(4323, 'modification', 'ˌmɒdɪfɪˈkeɪʃən', 'noun', '{"zh-TW":["修改；調整","變更"],"en":["a small change made","the act of modifying"]}', NULL, 'product modification/contract modification', '[{"en":"Please review the proposed modifications.","zh-TW":"請審查建議的修改。"}]', '{"verb":"modify","adjective":"modified"}', NULL, 4, 4323, 595),
(4324, 'modify', '/ˈmɒdɪfaɪ/', 'verb', '{"zh-TW":["修改；調整"],"en":["to make partial changes to something"]}', '{"root":{"text":"mod","meaning":"manner/measure (方式/適度)"},"suffix":{"text":"-ify","meaning":"make (使)"},"logic":"使其改變方式，即「修改」。"}', 'modify a plan / modify behavior / genetically modified; modify a plan/design/policy', '[{"en":"We need to modify the design slightly.","zh-TW":"我們需要稍微修改設計。"},{"en":"The software has been modified to fix the bug.","zh-TW":"軟體已被修改以修復錯誤。"},{"en":"We need to modify the proposal based on feedback.","zh-TW":"我們需要根據反饋修改提案。"},{"en":"The software was modified to fix the bug.","zh-TW":"軟體被修改以修復錯誤。"}]', '{"noun":"modification","adjective":"modified","verb":"modify"}', NULL, 2, 4324, 159),
(4325, 'modular', '/ˈmɒdjʊlər/', 'adjective', '{"zh-TW":["模組化的；組合式的"],"en":["employing or consisting of separable units or modules"]}', NULL, 'modular design / modular architecture / modular approach', '[{"en":"A modular software architecture allows components to be replaced independently.","zh-TW":"模組化軟件架構允許組件獨立替換。"},{"en":"Modular construction methods reduce costs and accelerate building timelines.","zh-TW":"模組化建設方法降低成本並加快建設時間表。"}]', '{"noun":"module","adverb":"modularly"}', NULL, 3, 4325, NULL),
(4326, 'module', '/ˈmɒdjuːl/', 'noun', '{"zh-TW":["模組；課程單元"],"en":["a self-contained unit of a course of study"]}', NULL, 'complete a module / module assessment', '[{"en":"Each module includes readings, videos, and a quiz.","zh-TW":"每個課程單元包含閱讀材料、影片和測驗。"},{"en":"The course is divided into six modules.","zh-TW":"課程分為六個單元。"}]', NULL, NULL, 2, 4326, 893),
(4327, 'moisture', '/ˈmɔɪstʃər/', 'noun', '{"zh-TW":["水分；濕氣"],"en":["tiny drops of water in the air or on a surface"]}', '{"root":{"text":"moist","meaning":"wet (潮濕)"},"suffix":{"text":"-ure","meaning":"state (狀態)"},"logic":"潮濕的狀態，即「水分」。"}', 'moisture level / retain moisture', '[{"en":"The cream helps your skin retain moisture.","zh-TW":"這款乳霜幫助肌膚保持水分。"},{"en":"Excess moisture can cause mold growth.","zh-TW":"過多的濕氣會導致黴菌生長。"}]', '{"adjective":"moist","verb":"moisturize","noun":"moisturizer"}', NULL, 3, 4327, NULL),
(4328, 'moment', '/ˈmoʊmənt/', 'noun', '{"zh-TW":["片刻；時刻"],"en":["a very short period of time"]}', NULL, 'at the moment / for the moment', '[{"en":"I am busy at the moment.","zh-TW":"我目前很忙。"},{"en":"For the moment, let''s wait.","zh-TW":"暫時我們等一下。"}]', '{"noun":"moment","adjective":"momentary","adjective2":"momentous"}', NULL, 2, 4328, NULL),
(4329, 'momentum', '/moʊˈmentəm/', 'noun', '{"zh-TW":["動力；勢頭"],"en":["the force gained by movement; impetus"]}', NULL, 'gain/build/lose momentum', '[{"en":"The project is gaining momentum.","zh-TW":"該項目正在獲得動力。"},{"en":"We must not lose the momentum we have built.","zh-TW":"我們不能失去已經建立的勢頭。"}]', '{"noun":"momentum"}', NULL, 3, 4329, NULL),
(4330, 'monetary', '/ˈmɑːnɪteri/', 'adjective', '{"zh-TW":["貨幣的；金融的"],"en":["relating to money or currency"]}', NULL, 'monetary policy / monetary value / monetary system', '[{"en":"The central bank adjusted its monetary policy.","zh-TW":"央行調整了其貨幣政策。"},{"en":"The painting has both monetary and sentimental value.","zh-TW":"這幅畫既有金錢價值，也有情感價值。"}]', '{"noun":"money","adjective":"monetary"}', NULL, 3, 4330, NULL),
(4331, 'monetary policy', '/ˈmɒnɪtəri ˈpɒlɪsi/', 'noun', '{"zh-TW":["貨幣政策"],"en":["central bank management of money supply and interest rates"]}', NULL, 'tighten monetary policy / loose monetary policy / monetary policy decision', '[{"en":"The central bank tightened monetary policy to cool inflation.","zh-TW":"中央銀行收緊貨幣政策以遏制通貨膨脹。"},{"en":"Monetary policy decisions affect borrowing costs nationwide.","zh-TW":"貨幣政策決定影響全國的借貸成本。"}]', '{"adjective":"monetary"}', NULL, 5, 4331, NULL),
(4332, 'monetary union', '/ˈmɒnɪtəri ˈjuːnjən/', 'noun', '{"zh-TW":["貨幣聯盟"],"en":["an agreement between countries to share a single currency and monetary policy"]}', NULL, 'join a monetary union / monetary union benefits', '[{"en":"Member states of a monetary union give up independent exchange rate policy.","zh-TW":"貨幣聯盟成員國放棄了獨立的匯率政策。"},{"en":"A monetary union reduces transaction costs in cross-border trade.","zh-TW":"貨幣聯盟降低了跨境貿易中的交易成本。"}]', NULL, NULL, 5, 4332, NULL),
(4333, 'monetize', '/ˈmɒnɪtaɪz/', 'verb', '{"zh-TW":["貨幣化；變現"],"en":["to convert an asset or activity into a source of income"]}', NULL, 'monetize a platform / monetize data / monetize content', '[{"en":"The startup found multiple ways to monetize its large user base.","zh-TW":"新創公司找到了多種方式將其龐大的用戶基礎變現。"},{"en":"Monetizing content through advertising is common for media companies.","zh-TW":"通過廣告將內容貨幣化對媒體公司來說很常見。"}]', '{"noun":"monetization","adjective":"monetized"}', NULL, 3, 4333, NULL),
(4334, 'money', '/ˈmʌni/', 'noun', '{"zh-TW":["金錢"],"en":["coins and notes used to buy things"]}', NULL, 'make money / money management', '[{"en":"The company makes money from subscriptions.","zh-TW":"公司靠訂閱賺錢。"},{"en":"Good money management is essential.","zh-TW":"良好的資金管理至關重要。"}]', '{"noun":"money","adjective":"monetary"}', NULL, 2, 4334, NULL),
(4335, 'money laundering', '/ˈmʌni ˈlɔːndərɪŋ/', 'noun', '{"zh-TW":["洗錢"],"en":["the process of making illegally obtained money appear legitimate"]}', NULL, 'prevent money laundering / anti-money laundering', '[{"en":"Banks must implement anti-money laundering controls.","zh-TW":"銀行必須實施反洗錢管控措施。"},{"en":"The compliance team monitors transactions to detect money laundering.","zh-TW":"合規團隊監控交易以發現洗錢行為。"}]', NULL, NULL, 5, 4335, NULL),
(4336, 'money market', '/ˈmʌni ˈmɑːrkɪt/', 'noun', '{"zh-TW":["貨幣市場"],"en":["the financial market for short-term borrowing and lending of funds"]}', NULL, 'invest in the money market / money market instrument', '[{"en":"Surplus funds were placed in money market instruments overnight.","zh-TW":"多餘資金被投入隔夜貨幣市場工具。"},{"en":"Money market rates influence the cost of short-term business financing.","zh-TW":"貨幣市場利率影響了短期商業融資成本。"}]', NULL, NULL, 4, 4336, NULL),
(4337, 'monitor', '/ˈmɒnɪtər/', 'verb', '{"zh-TW":["監控；監視","監控器；監視器","監控；監測"],"en":["to observe and check over a period of time","a screen or device for observing","to observe and check over time"]}', '{"root":{"text":"monit","meaning":"warn (警告)"},"suffix":{"text":"-or","meaning":"that which (…的東西)"},"logic":"提出警告的觀察，即「監控」。"}', 'monitor progress / monitor closely / heart monitor; monitor progress/performance/activity', '[{"en":"We will monitor the situation closely.","zh-TW":"我們將密切監控局勢。"},{"en":"The doctor monitors his blood pressure regularly.","zh-TW":"醫生定期監測他的血壓。"},{"en":"We use software to monitor network activity.","zh-TW":"我們使用軟體來監控網路活動。"},{"en":"The team monitors customer satisfaction closely.","zh-TW":"團隊密切監測客戶滿意度。"}]', '{"noun":"monitor","noun2":"monitoring","verb":"monitor"}', NULL, 3, 4337, 160),
(4338, 'monograph', '/ˈmɒnəɡrɑːf/', 'noun', '{"zh-TW":["專題論著；學術專著"],"en":["a detailed written study of a single specialized subject"]}', NULL, 'academic monograph / publish a monograph / scholarly monograph', '[{"en":"The historian published a monograph on the economic causes of the revolution.","zh-TW":"歷史學家發表了一部關於革命經濟原因的學術專著。"},{"en":"A monograph demonstrates mastery of a narrow but important topic.","zh-TW":"專題論著展示了對一個狹窄但重要主題的精通程度。"}]', NULL, NULL, 3, 4338, NULL),
(4339, 'monologue', '/ˈmɒnəlɒɡ/', 'noun', '{"zh-TW":["獨白；長篇大論"],"en":["a long speech by one person; a dramatic piece performed by one actor"]}', NULL, 'dramatic monologue / interior monologue / deliver a monologue', '[{"en":"The actor''s monologue captured the character''s inner turmoil beautifully.","zh-TW":"演員的獨白精美地捕捉了角色的內心動盪。"},{"en":"She performed a ten-minute monologue at the audition.","zh-TW":"她在試鏡時表演了十分鐘的獨白。"}]', '{"adjective":"monologic"}', NULL, 3, 4339, NULL),
(4340, 'monopolize', '/məˈnɑːpəlaɪz/', 'verb', '{"zh-TW":["壟斷；獨占"],"en":["to have exclusive control over"]}', NULL, 'monopolize the market/conversation', '[{"en":"One company should not monopolize the entire market.","zh-TW":"一家公司不應壟斷整個市場。"},{"en":"He tends to monopolize every meeting.","zh-TW":"他傾向於在每次會議中獨占發言。"}]', '{"noun":"monopoly","verb":"monopolize","adjective":"monopolistic"}', NULL, 4, 4340, NULL),
(4341, 'monopoly', '/məˈnɑːpəli/', 'noun', '{"zh-TW":["壟斷；獨占"],"en":["exclusive control of a commodity or service"]}', NULL, 'have a monopoly on / break a monopoly', '[{"en":"The company has a virtual monopoly on the market.","zh-TW":"該公司幾乎壟斷了市場。"},{"en":"The government moved to break up the monopoly.","zh-TW":"政府採取行動打破壟斷。"}]', '{"noun":"monopoly","verb":"monopolize","adjective":"monopolistic"}', NULL, 3, 4341, NULL),
(4342, 'monopsony', '/mɒˈnɒpsəni/', 'noun', '{"zh-TW":["買方壟斷"],"en":["a market situation in which only one buyer substantially controls the market as a purchaser"]}', NULL, 'labor monopsony / monopsony power / monopsony market', '[{"en":"A monopsony in the labor market allows one employer to set below-competitive wages.","zh-TW":"勞動力市場的買方壟斷使一個雇主能夠設定低於競爭水平的工資。"},{"en":"Amazon has been accused of using monopsony power in its dealings with suppliers.","zh-TW":"亞馬遜被指控在與供應商的交易中使用買方壟斷力量。"}]', '{"adjective":"monopsonistic"}', NULL, 3, 4342, NULL),
(4343, 'monsoon', '/mɒnˈsuːn/', 'noun', '{"zh-TW":["季風；雨季"],"en":["a seasonal wind bringing heavy rain"]}', '{"root":{"text":"mausim","meaning":"season (季節)"},"logic":"源自阿拉伯語 mausim（季節），指季節性風帶來的大雨。"}', 'monsoon season / monsoon rain', '[{"en":"The monsoon season brings heavy rainfall.","zh-TW":"雨季帶來大量降雨。"},{"en":"Flooding is common during the monsoon.","zh-TW":"雨季期間洪水很常見。"}]', '{"adjective":"monsoonal"}', NULL, 3, 4343, NULL),
(4344, 'month', '/mʌnθ/', 'noun', '{"zh-TW":["月份"],"en":["one of the twelve periods of a year"]}', NULL, 'per month / month-end', '[{"en":"Revenue increased month over month.","zh-TW":"營收逐月增加。"},{"en":"The report is due at month-end.","zh-TW":"報告月底截止。"}]', '{"noun":"month","adjective":"monthly"}', NULL, 2, 4344, NULL),
(4345, 'monthly recurring revenue', '/ˈmʌnθli rɪˈkɜːrɪŋ ˈrevənjuː/', 'noun', '{"zh-TW":["每月經常性收入"],"en":["the predictable revenue a business expects to receive every month from subscriptions"]}', NULL, 'track monthly recurring revenue / grow monthly recurring revenue', '[{"en":"The SaaS company''s monthly recurring revenue grew 15% quarter over quarter.","zh-TW":"SaaS公司的每月經常性收入環比增長了15%。"},{"en":"Investors value SaaS companies highly based on monthly recurring revenue.","zh-TW":"投資者根據每月經常性收入高度評估SaaS公司的價值。"}]', '{"abbreviation":"MRR"}', NULL, 5, 4345, NULL),
(4346, 'monthly report', '/ˈmʌnθli rɪˈpɔːrt/', 'noun', '{"zh-TW":["月度報告；月報"],"en":["a regular report covering a company performance over the previous month"]}', NULL, 'submit a monthly report / review the monthly report', '[{"en":"All department heads submit monthly reports on the fifth of each month.","zh-TW":"所有部門主管在每月五日提交月度報告。"},{"en":"Monthly reports track progress against annual targets.","zh-TW":"月度報告追蹤年度目標的進展。"}]', NULL, NULL, 5, 4346, NULL),
(4347, 'monument', '/''mɒnjʊmənt/', 'noun', '{"zh-TW":["紀念碑；遺址"],"en":["a statue or structure erected to commemorate a notable person or event"]}', NULL, 'erect a monument / national monument / historic monument', '[{"en":"The monument was erected to honor soldiers who died in the war.","zh-TW":"這座紀念碑是為了紀念在戰爭中犧牲的士兵而建立的。"},{"en":"Tourists flocked to photograph the iconic monument at sunset.","zh-TW":"遊客們蜂擁而至，在日落時分拍攝這座標誌性紀念碑。"}]', NULL, NULL, 3, 4347, NULL),
(4348, 'moral hazard', '/ˈmɒrəl ˈhæzərd/', 'noun', '{"zh-TW":["道德風險"],"en":["the tendency to take greater risks when one is insulated from the consequences"]}', NULL, 'reduce moral hazard / moral hazard in insurance', '[{"en":"Insurance creates moral hazard by reducing the insured''s incentive to avoid loss.","zh-TW":"保險通過降低被保險人避免損失的動力而產生了道德風險。"},{"en":"Moral hazard is a major concern in government bailouts of failing companies.","zh-TW":"道德風險是政府援助破產公司時的主要擔憂。"}]', NULL, NULL, 4, 4348, NULL),
(4349, 'moral panic', '/ˈmɒrəl ˈpænɪk/', 'noun', '{"zh-TW":["道德恐慌"],"en":["widespread fear about a perceived threat to social values"]}', NULL, 'media-fueled moral panic / create a moral panic / moral panic about youth', '[{"en":"The moral panic over video games led to excessive regulation.","zh-TW":"關於電子遊戲的道德恐慌導致了過度監管。"},{"en":"Social media amplifies moral panics by spreading alarm rapidly.","zh-TW":"社交媒體通過快速傳播警報來放大道德恐慌。"}]', NULL, NULL, 4, 4349, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(4350, 'morale', '/məˈræl/', 'noun', '{"zh-TW":["士氣；精神面貌"],"en":["the confidence and enthusiasm of a person or group"]}', NULL, 'boost/raise morale / low/high morale / employee morale', '[{"en":"Employee morale has improved since the new policy.","zh-TW":"自從新政策實施以來，員工士氣有所提高。"},{"en":"The bonus helped boost team morale.","zh-TW":"獎金有助於提振團隊士氣。"}]', '{"noun":"morale"}', NULL, 2, 4350, NULL),
(4351, 'moratorium', '/ˌmɒrəˈtɔːriəm/', 'noun', '{"zh-TW":["暫停；延期執行"],"en":["a temporary suspension of an activity or obligation"]}', NULL, 'declare a moratorium / lift a moratorium / debt moratorium', '[{"en":"The government declared a moratorium on evictions during the crisis.","zh-TW":"政府在危機期間宣佈暫停驅逐令。"},{"en":"A debt moratorium gave companies time to restructure their obligations.","zh-TW":"債務延期給予公司時間重組其義務。"}]', '{"plural":"moratoriums"}', NULL, 4, 4351, NULL),
(4352, 'moreover', '/mɔːrˈoʊvər/', 'adverb', '{"zh-TW":["此外；而且"],"en":["in addition to what has been said"]}', NULL, 'moreover, ... (sentence connector)', '[{"en":"The plan is cost-effective; moreover, it is environmentally friendly.","zh-TW":"這個計劃具有成本效益；此外，它還環保。"},{"en":"Moreover, the new system will save time.","zh-TW":"此外，新系統將節省時間。"}]', '{"adverb":"moreover"}', NULL, 3, 4352, NULL),
(4353, 'morning', '/ˈmɔːrnɪŋ/', 'noun', '{"zh-TW":["早上；上午"],"en":["the early part of the day"]}', NULL, 'good morning / morning shift', '[{"en":"Good morning, everyone.","zh-TW":"大家早安。"},{"en":"The morning shift starts at 6 a.m.","zh-TW":"早班從早上6點開始。"}]', '{"noun":"morning"}', NULL, 3, 4353, NULL),
(4354, 'mortgage', '/ˈmɔːrɡɪdʒ/', 'noun, verb', '{"zh-TW":["抵押貸款；房貸"],"en":["a loan for buying property, secured against that property"]}', NULL, 'mortgage payment / pay off a mortgage / mortgage rate', '[{"en":"They took out a 30-year mortgage on their house.","zh-TW":"他們辦了一筆30年的房貸。"},{"en":"Mortgage rates have increased this quarter.","zh-TW":"本季度房貸利率有所上升。"}]', '{"noun":"mortgage","verb":"mortgage"}', NULL, 3, 4354, NULL),
(4355, 'mortgage approval', '/''mɔːrɡɪdʒ əˌpruːvəl/', 'noun', '{"zh-TW":["按揭批准；房貸核准"],"en":["official confirmation from a lender that a mortgage application has been accepted"]}', NULL, 'receive mortgage approval / obtain mortgage approval / conditional mortgage approval', '[{"en":"She received mortgage approval after submitting three years of financial statements.","zh-TW":"她在提交三年財務報表後獲得了按揭批准。"},{"en":"Mortgage approval was conditional on the property passing a structural survey.","zh-TW":"按揭批准以房產通過結構檢測為條件。"}]', NULL, NULL, 5, 4355, NULL),
(4356, 'mortgage backed security', '/ˈmɔːrɡɪdʒ bækt sɪˈkjʊərɪti/', 'noun', '{"zh-TW":["抵押擔保證券"],"en":["a financial instrument backed by a pool of mortgage loans"]}', NULL, 'issue mortgage backed securities / mortgage backed security risk', '[{"en":"Banks package mortgages into mortgage backed securities to free up capital.","zh-TW":"銀行將抵押貸款打包成抵押擔保證券以釋放資本。"},{"en":"The financial crisis was linked to high-risk mortgage backed securities.","zh-TW":"金融危機與高風險抵押擔保證券有關。"}]', '{"abbreviation":"MBS"}', NULL, 5, 4356, NULL),
(4357, 'mortgage broker', '/''mɔːrɡɪdʒ ˌbrəʊkər/', 'noun', '{"zh-TW":["按揭經紀人；房貸中介"],"en":["a professional who acts as an intermediary between borrowers and mortgage lenders"]}', NULL, 'use a mortgage broker / consult a mortgage broker / mortgage broker fee', '[{"en":"A mortgage broker helped them find the best interest rate from dozens of lenders.","zh-TW":"一位按揭經紀人幫助他們從數十家貸款機構中找到了最佳利率。"},{"en":"Mortgage brokers charge a fee but can save borrowers significant money on their loan.","zh-TW":"按揭經紀人收取費用，但可以為借款人在貸款上節省大量資金。"}]', NULL, NULL, 5, 4357, NULL),
(4358, 'mortgage refinancing', '/''mɔːrɡɪdʒ ˌriːfaɪnænsɪŋ/', 'noun', '{"zh-TW":["按揭再融資；重新貸款"],"en":["replacing an existing mortgage with a new one, often to obtain a lower interest rate"]}', NULL, 'consider mortgage refinancing / complete mortgage refinancing / benefit of mortgage refinancing', '[{"en":"She refinanced her mortgage to take advantage of lower interest rates.","zh-TW":"她對按揭進行再融資，以利用較低的利率。"},{"en":"Mortgage refinancing can reduce monthly payments and save thousands over the loan term.","zh-TW":"按揭再融資可以減少每月還款額，並在貸款期限內節省數千元。"}]', '{"verb":"refinance"}', NULL, 5, 4358, NULL),
(4359, 'mortgage-backed', '/ˈmɔːrɡɪdʒ bækt/', 'adjective', '{"zh-TW":["抵押支持的"],"en":["secured by a pool of mortgages"]}', NULL, 'mortgage-backed securities / mortgage-backed investment', '[{"en":"Mortgage-backed securities package many home loans for investors.","zh-TW":"抵押支持證券為投資者打包了許多住房貸款。"},{"en":"The mortgage-backed bond offered stable returns for pension funds.","zh-TW":"抵押支持債券為退休基金提供了穩定回報。"}]', NULL, NULL, 5, 4359, NULL),
(4360, 'mother', '/ˈmʌðər/', 'noun', '{"zh-TW":["母親"],"en":["a female parent"]}', NULL, 'mother company / mother tongue', '[{"en":"English is not my mother tongue.","zh-TW":"英文不是我的母語。"},{"en":"The mother company is based in Germany.","zh-TW":"母公司在德國。"}]', '{"noun":"mother","adjective":"motherly","noun2":"motherhood"}', NULL, 2, 4360, NULL),
(4361, 'motif', '/məʊˈtiːf/', 'noun', '{"zh-TW":["主題；動機（文藝）"],"en":["a recurring subject or theme in art, literature, or music"]}', NULL, 'recurring motif / central motif / musical motif', '[{"en":"The snake is a powerful motif throughout the novel.","zh-TW":"蛇是整部小說中一個強有力的主題。"},{"en":"The composer used a simple four-note motif as the basis for the symphony.","zh-TW":"作曲家以一個簡單的四音動機作為交響樂的基礎。"}]', NULL, NULL, 2, 4361, NULL),
(4362, 'motion sickness', '/ˈməʊʃən ˈsɪknɪs/', 'noun', '{"zh-TW":["暈車；暈機"],"en":["nausea caused by travel in a vehicle"]}', NULL, 'suffer from motion sickness / prevent motion sickness', '[{"en":"She takes medication to prevent motion sickness on long trips.","zh-TW":"她在長途旅行時服藥預防暈車。"},{"en":"Motion sickness is common during turbulent flights.","zh-TW":"在亂流飛行中暈機是很常見的。"}]', NULL, NULL, 5, 4362, NULL),
(4363, 'motivate', '/ˈmoʊtɪveɪt/', 'verb', '{"zh-TW":["激勵；驅動"],"en":["to give someone a reason for doing something"]}', NULL, 'motivate employees/staff / highly motivated', '[{"en":"Good leaders know how to motivate their team.","zh-TW":"好的領導者知道如何激勵團隊。"},{"en":"She is a highly motivated individual.","zh-TW":"她是一個非常積極進取的人。"}]', '{"noun":"motivation, motive","verb":"motivate","adjective":"motivated, motivational"}', NULL, 3, 4363, NULL),
(4364, 'motivated', 'ˈmoʊtɪveɪtɪd', 'adjective', '{"zh-TW":["積極的；有動力的","受激勵的"],"en":["enthusiastic about working","driven by purpose"]}', NULL, 'highly motivated/motivated team', '[{"en":"We need a motivated and dedicated team.","zh-TW":"我們需要一個積極且專注的團隊。"}]', '{"verb":"motivate","noun":"motivation","adverb":"with motivation"}', NULL, 3, 4364, NULL),
(4365, 'motivation', 'ˌmoʊtɪˈveɪʃən', 'noun', '{"zh-TW":["動機；激勵","熱情"],"en":["a reason or drive to act","encouragement to do something"]}', NULL, 'employee motivation/self-motivation', '[{"en":"Motivation is key to high performance.","zh-TW":"動機是高績效的關鍵。"}]', '{"verb":"motivate","adjective":"motivated","adverb":"with motivation"}', NULL, 4, 4365, 597),
(4366, 'motivation theory', '/''məʊtɪˌveɪʃən ˌθɪərɪ/', 'noun', '{"zh-TW":["動機理論；激勵理論"],"en":["an academic or psychological framework that explains why people are driven to behave in certain ways"]}', NULL, 'apply motivation theory / motivation theory in management / Maslow''s motivation theory', '[{"en":"Maslow''s motivation theory suggests that basic needs must be met before higher goals can be pursued.","zh-TW":"馬斯洛的動機理論認為，在追求更高目標之前，必須滿足基本需求。"},{"en":"Understanding motivation theory can help managers design better incentive systems for their teams.","zh-TW":"理解動機理論可以幫助管理者為其團隊設計更好的激勵系統。"}]', '{"noun":"motivation","noun2":"theory"}', NULL, 5, 4366, NULL),
(4367, 'mount', '/maʊnt/', 'verb', '{"zh-TW":["增加；發起；安裝"],"en":["to increase; to organize; to fix in place"]}', NULL, 'mount a campaign / pressure mounts / mounting costs', '[{"en":"Pressure is mounting on the company to cut costs.","zh-TW":"要求公司削減成本的壓力越來越大。"},{"en":"The organization mounted a fundraising campaign.","zh-TW":"該組織發起了一場籌款活動。"}]', '{"noun":"mount","verb":"mount","adjective":"mounting"}', NULL, 2, 4367, NULL),
(4368, 'mountain', '/ˈmaʊntən/', 'noun', '{"zh-TW":["山"],"en":["a very high hill"]}', NULL, 'mountain of work / make a mountain out of a molehill', '[{"en":"I have a mountain of paperwork.","zh-TW":"我有一大堆文書工作。"},{"en":"Don''t make a mountain out of a molehill.","zh-TW":"不要小題大做。"}]', '{"noun":"mountain","adjective":"mountainous"}', NULL, 3, 4368, NULL),
