(4370, 'mouthfeel', '/''maʊθfiːl/', 'noun', '{"zh-TW":["口感；食物在口中的質地感"],"en":["the physical sensation experienced in the mouth when eating or drinking something"]}', NULL, 'smooth mouthfeel / rich mouthfeel / improve mouthfeel', '[{"en":"The chef added cream to the sauce to give it a richer mouthfeel.","zh-TW":"廚師在醬汁中加入了奶油，使其口感更豐富。"},{"en":"Wine experts evaluate mouthfeel when assessing body and texture.","zh-TW":"葡萄酒專家在評估酒體和質地時會評估口感。"}]', NULL, NULL, 3, 4370, NULL),
(4371, 'move', '/muːv/', 'verb', '{"zh-TW":["移動；搬遷；措施"],"en":["to change position","an action taken"]}', NULL, 'make a move / move forward', '[{"en":"It is time to make a move.","zh-TW":"是時候採取行動了。"},{"en":"Let''s move forward with the plan.","zh-TW":"讓我們推進這個計畫。"}]', '{"verb":"move","noun":"move","noun2":"movement","adjective":"moving"}', NULL, 1, 4371, NULL),
(4372, 'move the needle', '/muːv ðə ˈniːdəl/', 'verb', '{"zh-TW":["產生顯著影響；有所改變"],"en":["to produce a noticeable change in performance or results"]}', NULL, 'move the needle on growth / move the needle significantly', '[{"en":"The new marketing campaign moved the needle on customer awareness.","zh-TW":"新的行銷活動對客戶認知度產生了顯著影響。"},{"en":"Only bold initiatives will move the needle in a stagnant market.","zh-TW":"只有大膽的舉措才能在停滯的市場中有所改變。"}]', NULL, NULL, 5, 4372, NULL),
(4373, 'move-in ready', '/''muːv ɪn ˌredi/', 'adjective', '{"zh-TW":["可立即入住的；整裝待入的"],"en":["describing a property that is clean and in good condition and can be occupied immediately"]}', NULL, 'move-in ready condition / completely move-in ready / purchase move-in ready', '[{"en":"Buyers who want to avoid renovation work look for move-in ready properties.","zh-TW":"想要避免裝修工作的買家尋找可立即入住的房產。"},{"en":"The apartment was fully renovated and move-in ready when we first viewed it.","zh-TW":"我們第一次看房時，公寓已完全翻新且可立即入住。"}]', NULL, NULL, 5, 4373, NULL),
