(4376, 'multi-currency account', '/ˌmʌltiˈkʌrənsi əˈkaʊnt/', 'noun', '{"zh-TW":["多幣種帳戶"],"en":["a bank account that can hold funds in multiple foreign currencies"]}', NULL, 'open a multi-currency account / multi-currency account benefits', '[{"en":"A multi-currency account eliminates the need to convert currencies for each transaction.","zh-TW":"多幣種帳戶消除了每次交易轉換貨幣的需要。"},{"en":"Exporters use multi-currency accounts to manage foreign exchange efficiently.","zh-TW":"出口商使用多幣種帳戶高效管理外匯。"}]', NULL, NULL, 5, 4376, NULL),
(4377, 'multilateral agreement', '/ˌmʌltiˈlætərəl əˈɡriːmənt/', 'noun', '{"zh-TW":["多邊協議"],"en":["an agreement among three or more parties, often countries or organizations"]}', NULL, 'negotiate a multilateral agreement / multilateral agreement framework', '[{"en":"The multilateral agreement reduced trade tariffs among 12 member countries.","zh-TW":"多邊協議降低了12個成員國之間的貿易關稅。"},{"en":"A multilateral agreement requires consensus from all participating parties.","zh-TW":"多邊協議需要所有參與方的共識。"}]', '{"opposite":"bilateral agreement"}', NULL, 5, 4377, NULL),
