(4381, 'multimodal transport', '/''mʌltiˌməʊdəl ˌtrænspɔːrt/', 'noun', '{"zh-TW":["多式聯運；複合運輸"],"en":["the movement of goods using two or more modes of transportation under a single contract"]}', NULL, 'use multimodal transport / multimodal transport solution / benefits of multimodal transport', '[{"en":"Multimodal transport combines sea and rail freight to reduce costs and emissions.","zh-TW":"多式聯運結合了海運和鐵路貨運，以降低成本和排放。"},{"en":"The shipper chose multimodal transport to balance cost and delivery speed.","zh-TW":"發貨方選擇了多式聯運，以平衡成本和配送速度。"}]', NULL, NULL, 5, 4381, NULL),
