(4385, 'multiplier effect', '/ˈmʌltɪplaɪər ɪˈfekt/', 'noun', '{"zh-TW":["乘數效應"],"en":["the amplified impact of an initial economic change on total income"]}', NULL, 'fiscal multiplier effect / investment multiplier effect / multiplier effect in economics', '[{"en":"Government spending has a multiplier effect on economic output.","zh-TW":"政府支出對經濟產出具有乘數效應。"},{"en":"Infrastructure investment generates a multiplier effect through supply chain activity.","zh-TW":"基礎設施投資通過供應鏈活動產生乘數效應。"}]', NULL, NULL, 5, 4385, NULL),
