(4390, 'mural', '/ˈmjʊrəl/', 'noun', '{"zh-TW":["壁畫"],"en":["a painting done directly on a wall"]}', '{"root":{"text":"mur","meaning":"wall (牆)"},"suffix":{"text":"-al","meaning":"relating to (相關的)"},"logic":"與牆相關的繪畫，即「壁畫」。"}', 'paint a mural / street mural', '[{"en":"The artist painted a mural on the building.","zh-TW":"藝術家在建築物上畫了一幅壁畫。"},{"en":"The city is famous for its colorful murals.","zh-TW":"這座城市以色彩繽紛的壁畫聞名。"}]', '{"noun":"muralist"}', NULL, 2, 4390, NULL),
